static int nx_fixture_map_page(uintptr_t address,size_t size) {
    void *got=mmap((void *)address,size,PROT_READ|PROT_WRITE,MAP_PRIVATE|MAP_ANONYMOUS|MAP_FIXED,-1,0);
    return got==(void *)address;
}
static volatile int nx_fixture_stopping;
static void *nx_fixture_videosrc(void *unused){(void)unused;prctl(PR_SET_NAME,"videosrc");while(!nx_fixture_stopping)usleep(10000);return 0;}
static void *nx_fixture_udd(void *unused){(void)unused;prctl(PR_SET_NAME,"udd_intr_handle");while(!nx_fixture_stopping)usleep(10000);return 0;}
static int nx_fixture_identity(void) {
    if(!nx_fixture_map_page(0x4c9000,0x6000)||!nx_fixture_map_page(0x4de000,0x2000)||
       !nx_fixture_map_page(0x240000,0xd000)||!nx_fixture_map_page(0xf0000,0x10000)||
       !nx_fixture_map_page(0x80000,0x6000)||!nx_fixture_map_page(0x107000,0x1000)||
       !nx_fixture_map_page(0x1bb000,0x1000)) return 0;
    if(prctl(PR_SET_NAME,"di-camera-app-")!=0) return 0;
    for(unsigned i=0;i<sizeof nx_fixture_accessors/sizeof nx_fixture_accessors[0];i++)
        memcpy((void *)(uintptr_t)nx_fixture_accessors[i].address,nx_fixture_accessors[i].bytes,
               nx_fixture_accessors[i].size);
    /* Use the real-device liveview value, not the old fixture marker 7. The
     * panel and the loader both gate on this; a fixture that only supplies 7
     * cannot catch a gate that rejects the device value 2231780. */
    *(volatile uint32_t *)(uintptr_t)(0x24c838u+0x34u)=2231780u;
    *(volatile uint32_t *)(uintptr_t)0x4c9f04u=0x24c838u;
    *(volatile uint32_t *)(uintptr_t)0x4c9c5cu=0x24c0b8u;
    *(volatile uint32_t *)(uintptr_t)0x4c9c64u=0x4c9f04u;
    *(volatile uint32_t *)(uintptr_t)0x4de4d4u=18u;
    /* Liveview readiness requires at least one videosrc and two udd_intr_handle
     * threads (the healthy device runs two interrupt workers). */
    pthread_t a,b,c;
    if(pthread_create(&a,0,nx_fixture_videosrc,0)||pthread_create(&b,0,nx_fixture_udd,0)||
       pthread_create(&c,0,nx_fixture_udd,0)) return 0;
    return 1;
}
